import com.fasterxml.jackson.module.kotlin.KotlinModule;
import io.dropwizard.Application;
import io.dropwizard.configuration.EnvironmentVariableSubstitutor;
import io.dropwizard.configuration.SubstitutingSourceProvider;
import io.dropwizard.setup.Bootstrap;
import io.dropwizard.setup.Environment;
import org.dhatim.dropwizard.prometheus.PrometheusBundle;

public class PrimeApplication extends Application<PrimeConfiguration> {

    public static void main(String[] args) throws Exception {
        new PrimeApplication().run(args);
    }

    @Override
    public void initialize(Bootstrap<PrimeConfiguration> bootstrap) {
        bootstrap.setConfigurationSourceProvider(
            new SubstitutingSourceProvider(
                bootstrap.getConfigurationSourceProvider(),
                new EnvironmentVariableSubstitutor(false)
            )
        );
        bootstrap.getObjectMapper().registerModule(new KotlinModule());
        bootstrap.addBundle(new PrometheusBundle());
    }

    @Override
    public void run(PrimeConfiguration primeConfiguration, Environment environment) throws Exception {
        primeConfiguration.getModules().forEach(module -> module.init(environment));
    }
}"}

