import os
import re
from pathlib import Path

def update_pom_files():
    """Update all pom.xml files to remove Kotlin compilation and use Java only"""

    # Find all pom.xml files
    pom_files = []
    for root, dirs, files in os.walk('.'):
        for file in files:
            if file == 'pom.xml':
                pom_files.append(os.path.join(root, file))

    print(f"Found {len(pom_files)} pom.xml files to update")

    for pom_file in pom_files:
        if 'target' in pom_file or 'build' in pom_file:
            continue

        print(f"Processing: {pom_file}")

        try:
            with open(pom_file, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as e:
            print(f"Error reading {pom_file}: {e}")
            continue

        # Remove Kotlin dependencies (except for jackson-module-kotlin which might be needed)
        content = re.sub(r'<dependency>\s*<groupId>org\.jetbrains\.kotlin</groupId>\s*<artifactId>kotlin-stdlib[^<]*</artifactId>[^<]*</dependency>', '', content, flags=re.DOTALL)
        content = re.sub(r'<dependency>\s*<groupId>org\.jetbrains\.kotlinx</groupId>[^<]*</dependency>', '', content, flags=re.DOTALL)

        # Remove Kotlin plugin configuration
        content = re.sub(r'<plugin>\s*<groupId>org\.jetbrains\.kotlin</groupId>\s*<artifactId>kotlin-maven-plugin</artifactId>.*?</plugin>', '', content, flags=re.DOTALL)

        # Remove empty lines
        content = re.sub(r'\n\s*\n\s*\n', '\n\n', content)

        # Write updated content
        try:
            with open(pom_file, 'w', encoding='utf-8') as f:
                f.write(content)
            print(f"Updated: {pom_file}")
        except Exception as e:
            print(f"Error writing {pom_file}: {e}")

if __name__ == "__main__":
    update_pom_files()"}

