 */

// Access interfaces
public interface ClientDataSource extends ClientDocumentStore, ClientGraphStore {
}

public interface AdminDataSource extends ClientDataSource, AdminDocumentStore, AdminGraphStore {
}

// Generic interfaces
public interface ScanInformationStore {

    /**
     * Function to upsert scan information data from the 3rd party eKYC scan
     */
    Either<StoreError, Void> upsertVendorScanInformation(
            String customerId,
            String countryCode,
            java.util.Map<String, String> vendorData
    );

    /**
     * Get extended status information for scan
     */
    java.util.Map<String, String> getExtendedStatusInformation(String scanInformation);
}

public interface AuditLogStore {

    /**
     * Log Customer Activity so that we have activity history
     */
    void logCustomerActivity(String customerId, String customerActivity);

    /**
     * Get all customer activity history
     */
    Either<String, Collection<String>> getCustomerActivityHistory(String customerId);
}

// Type interfaces
public interface DocumentStore extends ClientDocumentStore, AdminDocumentStore, AuditLogStore {
}

public interface GraphStore extends ClientGraphStore, AdminGraphStore {
}

// Type instances - using static methods instead of global variables
public class StorageRegistry {

    public static DocumentStore getDocumentStore() {
        return ResourceRegistry.getResource(DocumentStore.class);
    }

    public static GraphStore getGraphStore() {
        return ResourceRegistry.getResource(GraphStore.class);
    }
}

// Implementation classes
public class ClientDataSourceImpl implements ClientDataSource {
    private final ClientDocumentStore documentStore;
    private final ClientGraphStore graphStore;

    public ClientDataSourceImpl() {
        this.documentStore = StorageRegistry.getDocumentStore();
        this.graphStore = StorageRegistry.getGraphStore();
    }

    // ClientDocumentStore methods
    @Override
    public Collection<String> getNotificationTokens(String customerId) {
        return documentStore.getNotificationTokens(customerId);
    }

    @Override
    public boolean addNotificationToken(String customerId, String token) {
        return documentStore.addNotificationToken(customerId, token);
    }

    @Override
    public String getNotificationToken(String customerId, String applicationID) {
        return documentStore.getNotificationToken(customerId, applicationID);
    }

    @Override
    public boolean removeNotificationToken(String customerId, String applicationID) {
        return documentStore.removeNotificationToken(customerId, applicationID);
    }

    // ClientGraphStore methods
    @Override
    public Either<StoreError, String> getCustomer(String identity) {
        return graphStore.getCustomer(identity);
    }

    @Override
    public Either<StoreError, Void> addCustomer(String identity, String customer, String referredBy) {
        return graphStore.addCustomer(identity, customer, referredBy);
    }

    @Override
    public Either<StoreError, Void> updateCustomer(String identity, String nickname, String contactEmail) {
        return graphStore.updateCustomer(identity, nickname, contactEmail);
    }

    @Override
    public Either<StoreError, Void> removeCustomer(String identity) {
        return graphStore.removeCustomer(identity);
    }

    @Override
    public Either<StoreError, java.util.Map<String, String>> getProducts(String identity) {
        return graphStore.getProducts(identity);
    }

    @Override
    public Either<StoreError, String> getProduct(String identity, String sku) {
        return graphStore.getProduct(identity, sku);
    }

    @Override
    public Either<StoreError, Collection<String>> getAllRegionDetails(String identity) {
        return graphStore.getAllRegionDetails(identity);
    }

    @Override
    public Either<StoreError, String> getRegionDetails(String identity, String regionCode) {
        return graphStore.getRegionDetails(identity, regionCode);
    }
}"}

