{"command": "create", "path": "/workspace/project/telco-core/jersey/src/main/java/org/ostelco/prime/jersey/YamlMessageBodyReader.java", "file_text": "package org.ostelco.prime.jersey;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory;

import javax.ws.rs.Consumes;
import javax.ws.rs.WebApplicationException;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.core.Response;
import javax.ws.rs.ext.MessageBodyReader;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

/**
 * JAX-RS message body reader for YAML content
 */
@Consumes("text/vnd.yaml")
public class YamlMessageBodyReader implements MessageBodyReader<Object> {

    private final ObjectMapper mapper = new ObjectMapper(new YAMLFactory());

    @Override
    public boolean isReadable(Class<?> type, Type genericType, Annotation[] annotations, MediaType mediaType) {
        return true;
    }

    @Override
    public Object readFrom(Class<Object> type, Type genericType, Annotation[] annotations, 
                          MediaType mediaType, MultivaluedMap<String, String> httpHeaders, 
                          InputStream inputStream) {
        try {
            return mapper.readValue(inputStream, type);
        } catch (Exception e) {
            throw new WebApplicationException("Failed to parse YAML: " + e.getMessage(), 
                    Response.Status.BAD_REQUEST);
        }
    }
}"}

